import{z as i,x as s,o as n,c as A,q as p,j as o,D as t,d as l,s as r,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"早退与自适应计算","description":"","frontmatter":{"title":"早退与自适应计算","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/early-exit-adaptive.md","filePath":"llm/early-exit-adaptive.md","lastUpdated":1791063341000}'),d={name:"llm/early-exit-adaptive.md"};function m(u,a,k,C,h,f){const E=s("Mermaid");return n(),A("div",null,[a[2]||(a[2]=p('<h1 id="早退与自适应计算" tabindex="-1">早退与自适应计算 <a class="header-anchor" href="#早退与自适应计算" aria-label="Permalink to &quot;早退与自适应计算&quot;">​</a></h1><div class="epigraph"><p>简单例子不必走完全深；在中间层接出分类头，用置信度决定是否停止前向。</p><footer>—— Xin et al., DeeBERT, ACL 2020；序列生成中的自适应见 Schuster et al., Confident Adaptive Language Modeling, 2022</footer></div><p><a href="/llm/looped-transformer">上一课</a>用全局 \\(T\\) 调计算，所有 token、所有样本同深。<a href="/llm/universal-transformer-recurrence">Universal Transformer</a> 的 ACT 已经按位置停机，但绑在共享块上。本课把早退接到<strong>普通不共享深层栈</strong>：中间层挂出口，推理时按置信度退出。这是部署侧的自适应计算，不必把模型改成循环体。下一课 ALBERT 回到参数共享，不再谈按例停机。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加深对难例有用，对易例浪费。语言模型里大量 token 是高频、局部可预测的，少数 token 需要全深。缺口是训练与推理一致的出口：中间表示必须已经能出词表或类别，且退出决策不能系统性地伤害尾部质量。</p><p>DeeBERT 对编码器分类在若干层接分类头，用熵或置信阈值早退。CALM 把类似想法接到自回归生成：每个 token 在中间层预测，置信则退出该 token 的剩余层。二者都要解决「出口头怎么训」和「阈值怎么定」。</p><p><span class="marginnote">「置信度」指出口头输出的概率分布有多「笃定」，常用最大概率或负熵衡量。直觉是：模型在简单 token 上很早就会很笃定（比如逗号后面大概率还是常用词），这类 token 不必再算后面十几层。</span></p><p><span class="marginnote">早退切的是深度，不是序列长度，也不是 KV 是否共享。YOCO、CLA 省的是缓存；早退省的是这一次前向还要不要算后面的 FFN 与注意力。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在层集 \\(\\mathcal{L}_{\\mathrm{exit}}\\) 上接共享或独立的输出头。训练策略两种：所有出口都对真标签算损失（联合训练），或先训满深再冻骨干训出口。联合训练让浅层表示也对齐任务，早退才有东西可用；只训深层则浅出口是后贴的探针，阈值很难稳。</p><p>推理：若出口 \\(k\\) 的 \\(\\max p\\) 或 \\(1-H(p)\\) 超过阈值则停止，否则继续。阈值可按层设，使浅层更严、深层更松。生成式 CALM 还要处理 KV：早退的 token 若没算深层注意力，深层缓存缺条目，后续 token 读深层时对不齐——必须规定早退 token 仍把某一层的 KV 投影到深层，或禁止在需要满缓存的解码器上按 token 不同深。</p><p><span class="marginnote">直觉类比：早退像考试「会做的题提前交卷」——出口 \\(k\\) 是做完第 \\(k\\) 部分时的临时判卷员，判「这答案已经稳了」就收卷，否则继续往下做。阈值就是判卷员的严格程度：浅层判卷员要更严（少冤枉），深层可以更松。</span></p><h3 id="与-act、loop-的关系" tabindex="-1">与 ACT、loop 的关系 <a class="header-anchor" href="#与-act、loop-的关系" aria-label="Permalink to &quot;与 ACT、loop 的关系&quot;">​</a></h3><p>ACT 把停机学进共享块内部。早退把停机放在固定层之间的出口，实现简单，和现有检查点兼容。Loop 的 \\(T\\) 是全局预算。三者都是自适应计算族，切的轴分别是共享迭代、层号、全局循环。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>浅层表示偏词汇与局部，深层偏长程与任务。联合损失迫使浅层也长出一个「够用就走」的决策面。置信校准往往不足：softmax 最大概率不能直接当正确率，阈值要在验证集按代价（延迟对准确）扫。过自信导致系统性早退错误，尤其是罕见格式与否定。</p><p>编码器分类没有 KV 对齐问题，早退最干净。自回归解码器的 KV 契约是主要工程边界，也是许多论文只在编码器或非自回归设置里报加速的原因。</p>',17)),(n(),o(B,null,{default:t(()=>[r(E,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22token%201%20%E5%9C%A8%E6%B5%85%E5%B1%82%E9%80%80%E5%87%BA%22%5D%20--%3E%20K1%5B%22%E6%B7%B1%E5%B1%82%20KV%20%E7%BC%BA%E6%9D%A1%E7%9B%AE%22%5D%0A%20%20T2%5B%22token%202%20%E8%B5%B0%E6%BB%A1%E6%B7%B1%22%5D%20--%3E%20K2%5B%22%E6%B7%B1%E5%B1%82%E6%B3%A8%E6%84%8F%E5%8A%9B%E8%A6%81%E8%AF%BB%20token%201%20%E7%9A%84%20KV%22%5D%0A%20%20K1%20--%3E%20FIX%5B%22%E8%A1%A5%E5%A5%91%E7%BA%A6%EF%BC%9A%E6%97%A9%E9%80%80%E5%B1%82%20KV%20%E6%8A%95%E5%BD%B1%E5%88%B0%E6%B7%B1%E5%B1%82%3Cbr%3E%E6%88%96%E7%A6%81%E6%AD%A2%E9%80%90%20token%20%E4%B8%8D%E5%90%8C%E6%B7%B1%22%5D%0A%20%20K2%20--%3E%20FIX%0A%20%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%E5%88%86%E7%B1%BB%22%5D%20--%3E%20OK%5B%22%E6%97%A0%E8%A7%A3%E7%A0%81%20KV%20%E5%A5%91%E7%BA%A6%3Cbr%3E%E6%97%A9%E9%80%80%E6%9C%80%E5%B9%B2%E5%87%80%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"这张图回答「解码器早退难在哪」：后面的 token 走深层时仍要读前面所有 token 的深层 KV，早退的 token 没算过深层、缓存缺条目，注意力就对不齐；编码器没有这种跨位置契约，所以许多早退论文只在编码器上报加速。")],-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"投机解码也是「浅网提议、深网验证」，但是两套模型或一套加草稿头，不是同一前向里的中间出口。不要把早退写成投机。")],-1)),a[5]||(a[5]=e("h2",{id:"边界",tabindex:"-1"},[l("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[6]||(a[6]=e("p",null,"加速比等于平均退出层对 \\(L\\) 的比，尾部难 token 仍跑满，延迟分位数改善小于均值。训练多出口会轻微拖累满深准确，这是税。阈值随领域漂，部署要按任务重扫。下一课不再用出口换计算，而用跨层共享换参数量——早退的头在共享层上会变成同一头的多次接入，语义不同。",-1)),(n(),o(B,null,{default:t(()=>[r(E,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E5%B1%821%22%5D%20--%3E%20E1%5B%22%E5%87%BA%E5%8F%A31%22%5D%0A%20%20E1%20--%3E%7C%22%E7%BD%AE%E4%BF%A1%E4%B8%8D%E8%B6%B3%22%7C%20L2%5B%22%E5%B1%822%22%5D%0A%20%20L2%20--%3E%20E2%5B%22%E5%87%BA%E5%8F%A32%22%5D%0A%20%20E2%20--%3E%7C%22%E7%BD%AE%E4%BF%A1%E4%B8%8D%E8%B6%B3%22%7C%20LD%5B%22%E6%9C%80%E6%B7%B1%E5%B1%82%22%5D%0A%20%20E1%20--%3E%7C%22%E8%B6%B3%E5%A4%9F%22%7C%20Out%5B%22%E8%BE%93%E5%87%BA%22%5D%0A%20%20E2%20--%3E%20Out%0A%20%20LD%20--%3E%20Out%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[8]||(a[8]=e("ul",null,[e("li",null,"早退在固定深层栈的中间出口按置信停机，按例分配深度。"),e("li",null,"联合训练各出口才能让浅层表示可退出；只探针不够。"),e("li",null,"自回归 KV 对齐是解码器早退的硬边界；编码器分类更干净。"),e("li",null,"与 ACT、循环 \\(T\\)、投机解码分属不同机制。"),e("li",null,"出处：Xin et al., ACL 2020；Schuster et al., 2022。")],-1))])}const c=i(d,[["render",m]]);export{T as __pageData,c as default};
